window.kbPageData["views/entry/k-94187d1283fc8d88"] = {"key":"entry/k-94187d1283fc8d88","state":{"route":"entry/k-94187d1283fc8d88"},"node":{"id":"k-94187d1283fc8d88","mode":"k","title":"庆祝中国共产党成立 105 周年","type":"事实与事件","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["事实与事件"],"出处性质":["机构注释"],"学科":["政治理论"],"时间索引":["年度事件或数据"],"来源主题":["二十届五中全会"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"庆祝中国共产党成立 105 周年","slug":"27476c8feca6"}],"directorySummary":"8.庆祝中国共产党成立 105 周年\n2026 年是中国共产党成立 105 周年，习近平在庆祝中国共产党成立 105 周年大会\n上发表重要讲话，重点内容包括：\n（1）105 年不懈奋斗的五个方面成就：①105 年不懈奋斗，从根本上改变了中国\n人民的前途命运；②105 年不懈奋斗，开辟了实现中华民族伟…","sources":[{"id":"d421d38d3ac1f43b","label":"庆祝中国共产党成立 105 周年","topic":"二十届五中全会","category":"时政","text":"8.庆祝中国共产党成立 105 周年\n2026 年是中国共产党成立 105 周年，习近平在庆祝中国共产党成立 105 周年大会\n上发表重要讲话，重点内容包括：\n（1）105 年不懈奋斗的五个方面成就：①105 年不懈奋斗，从根本上改变了中国\n人民的前途命运；②105 年不懈奋斗，开辟了实现中华民族伟大复兴的正确道路；③\n105 年不懈奋斗，展示了马克思主义的强大生命力；④105 年不懈奋斗，深刻影响了世\n界历史进程；⑤105 年不懈奋斗，锻造了强大的中国共产党。\n（2）优秀特质“六个始终”：中国共产党之所以能够在 105 年奋斗中不断铸就辉\n煌，历史和人民之所以选择中国共产党，根本在于我们党具有其他政党和政治力量无\n可比拟的优秀特质。①矢志追求真理，始终把准前进方向；②深深植根人民，始终拥\n有坚实根基；③勇担历史使命，始终掌握战略主动；④顺应发展潮流，始终走在时代\n前列；⑤敢于善于斗争，始终保持必胜信心；⑥注重强健自身，始终充满生机活力。\n（3）五个必须：实现新时代新征程党的使命任务，要求全体中国共产党人坚定信\n心、接续奋斗，不断创造无愧于时代和人民的新业绩。①坚定信心、接续奋斗，必须\n坚持党的基本理论、基本路线、基本方略；②坚定信心、接续奋斗，必须紧紧依靠人\n民创造历史伟业；③坚定信心、接续奋斗，必须积极应对前进道路上的风险挑战；④\n坚定信心、接续奋斗，必须持续推动构建人类命运共同体；⑤坚定信心、接续奋斗，\n必须持之以恒推进全面从严治党。\n——《中国政府网》","source":{"doc":"41195a191a57c1c36332","first":5,"last":6,"page":5,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-94187d1283fc8d88":[]}};
